import math

def build_agent(sandbox):
    return None  # No agent components needed

def agent_action(sandbox, agent_body, step_count):
    # Determine current target based on checkpoint status
    if not sandbox.get_checkpoint_a_reached():
        target = (18.25, 4.15)  # Alpha center
    elif not sandbox.get_checkpoint_b_reached():
        target = (23.75, 2.85)  # Beta center
    else:
        target = (30, 2.5)  # Final target

    x_current, y_current = sandbox.get_sled_position()
    x_target, y_target = target

    # Calculate direction vector
    dx = x_target - x_current
    dy = y_target - y_current
    distance = math.hypot(dx, dy)

    # Check if in target's x and y ranges
    if not sandbox.get_checkpoint_a_reached():
        in_x_range = 17.5 <= x_current <= 19.0
        in_y_range = 3.8 <= y_current <= 4.5
    elif not sandbox.get_checkpoint_b_reached():
        in_x_range = 23.0 <= x_current <= 24.5
        in_y_range = 2.5 <= y_current <= 3.2
    else:
        in_x_range = 28.0 <= x_current <= 32.0
        in_y_range = 2.2 <= y_current <= 2.8

    # Calculate normalized direction vector
    if distance > 0:
        dir_x = dx / distance
        dir_y = dy / distance
    else:
        dir_x = 0
        dir_y = 0

    # Get current velocity
    vx, vy = sandbox.get_sled_velocity()
    speed = math.hypot(vx, vy)

    # Determine thrust magnitude based on distance and speed
    if distance > 15.0:
        thrust_magnitude = 600.0
    elif distance > 10.0:
        thrust_magnitude = 500.0
    elif distance > 5.0:
        thrust_magnitude = 400.0
    elif distance > 1.0:
        thrust_magnitude = 300.0
    else:
        thrust_magnitude = 200.0

    # Adjust thrust based on speed
    if speed > 5.0:
        thrust_magnitude = 300.0
    elif speed < 2.0:
        thrust_magnitude = 400.0
    else:
        thrust_magnitude = 500.0

    # Adjust vertical thrust based on y position
    if not in_y_range:
        # Adjust vertical thrust to move towards target y
        if y_current < y_target - 0.5:
            # Need to increase y
            dir_y += 0.1  # Adjust direction to increase y
        elif y_current > y_target + 0.5:
            # Need to decrease y
            dir_y -= 0.1  # Adjust direction to decrease y

    # Apply thrust in the direction of the target
    f1 = dir_x * thrust_magnitude
    f2 = dir_y * thrust_magnitude

    # Apply thrust
    sandbox.apply_thrust(f1, f2)
